package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net/http"
	"sync"
	"time"
)

type User struct {
	ID       string
	Username string
	Role     string
	Session  string
}

type RoleChange struct {
	UserID  string
	NewRole string
	Applied time.Time
}

var (
	users      = make(map[string]*User)
	sessions   = make(map[string]*User)
	roleQueue  = make([]RoleChange, 0)
	usersMu    sync.RWMutex
	sessionsMu sync.RWMutex
	queueMu    sync.Mutex
)

func generateToken() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func init() {
	admin := &User{ID: "u1", Username: "admin", Role: "admin", Session: "sess_admin"}
	regular := &User{ID: "u2", Username: "bob", Role: "viewer", Session: "sess_bob"}
	users["u1"] = admin
	users["u2"] = regular
	sessions["sess_admin"] = admin
	sessions["sess_bob"] = regular
}

func getAuthenticatedUser(r *http.Request) *User {
	token := r.Header.Get("X-Session-Token")
	if token == "" {
		return nil
	}
	sessionsMu.RLock()
	user := sessions[token]
	sessionsMu.RUnlock()
	return user
}

func resolveEffectiveRole(user *User) string {
	queueMu.Lock()
	defer queueMu.Unlock()

	for i, change := range roleQueue {
		if change.UserID == user.ID && time.Since(change.Applied) < 50*time.Millisecond {
			roleQueue = append(roleQueue[:i], roleQueue[i+1:]...)
			return change.NewRole
		}
	}
	return user.Role
}

func checkPermission(role string, action string) bool {
	permissions := map[string][]string{
		"admin":  {"read", "write", "delete", "manage_users"},
		"editor": {"read", "write"},
		"viewer": {"read"},
	}
	allowed, exists := permissions[role]
	if !exists {
		return false
	}
	for _, perm := range allowed {
		if perm == action {
			return true
		}
	}
	return false
}

func authorizeAction(user *User, action string) bool {
	role := resolveEffectiveRole(user)
	return checkPermission(role, action)
}

func handleDemoteUser(w http.ResponseWriter, r *http.Request) {
	caller := getAuthenticatedUser(r)
	if caller == nil {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}
	if !authorizeAction(caller, "manage_users") {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	targetID := r.URL.Query().Get("target")
	newRole := r.URL.Query().Get("role")
	if targetID == "" || newRole == "" {
		http.Error(w, "missing params", http.StatusBadRequest)
		return
	}
	queueMu.Lock()
	roleQueue = append(roleQueue, RoleChange{
		UserID:  targetID,
		NewRole: newRole,
		Applied: time.Now(),
	})
	queueMu.Unlock()

	usersMu.Lock()
	if u, ok := users[targetID]; ok {
		u.Role = newRole
	}
	usersMu.Unlock()
	fmt.Fprintf(w, "role updated for %s to %s", targetID, newRole)
}

func handleDeleteResource(w http.ResponseWriter, r *http.Request) {
	caller := getAuthenticatedUser(r)
	if caller == nil {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	// Step 1: Verify the caller has delete permission
	if !authorizeAction(caller, "delete") {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}

	// Step 2: Simulate async resource resolution (e.g., DB lookup)
	resourceID := r.URL.Query().Get("id")
	time.Sleep(30 * time.Millisecond)

	// Step 3: Re-read the user's current role from the live user object
	// This re-check uses the SAME user pointer obtained at authentication time
	// The role field on the pointed-to struct may have been mutated between steps
	usersMu.RLock()
	currentRole := caller.Role
	usersMu.RUnlock()

	if !checkPermission(currentRole, "delete") {
		http.Error(w, "permission revoked", http.StatusForbidden)
		return
	}

	fmt.Fprintf(w, "deleted resource %s", resourceID)
}

func main() {
	http.HandleFunc("/demote", handleDemoteUser)
	http.HandleFunc("/delete", handleDeleteResource)
	http.ListenAndServe(":8080", nil)
}
